@Service
public class OrderService {

    // Recommended: Constructor Injection with final immutability
    private final PaymentClient paymentClient;
    private final InventoryRepository inventoryRepository;

    public OrderService(PaymentClient paymentClient, InventoryRepository inventoryRepository) {
        this.paymentClient = paymentClient;
        this.inventoryRepository = inventoryRepository;
    }

    public void processOrder(Order order) {
        paymentClient.charge(order.getAmount());
        inventoryRepository.decrementStock(order.getItems());
    }
}
